{!REQUIRESCRIPT("/soap/ajax/51.0/connection.js")}
{!REQUIRESCRIPT("/soap/ajax/51.0/apex.js")}

var selectedRecords = {!GETRECORDIDS($ObjectType.Opportunity)};

if (selectedRecords.length === 0) {
    alert("Please select at least one Opportunity.");
} else {
    var result = confirm("Are you sure you want to update the selected Opportunities to 'Closed Won'?");
    if (result) {
        sforce.apex.execute(
            "MassUpdateOpportunityController", 
            "updateOpportunities", 
            { opportunityIds: selectedRecords }
        );
        alert("Opportunities updated successfully!");
        window.location.reload(); // Refresh the List View
    }
}
